class AccountWeatherApiTests(TestCase):
    class FakeWeatherResponse:
        def __init__(self, payload):
            self.payload = payload

        def raise_for_status(self):
            return None

        def json(self):
            return self.payload

    def setUp(self):
        cache.clear()
        self.user = get_user_model().objects.create_user(username="weather_user", password="pw123456")
        self.client.login(username="weather_user", password="pw123456")

    def reverse_response(self, *, korean=False):
        address = (
            {
                "suburb": "목5동",
                "quarter": "목동",
                "borough": "양천구",
                "city": "서울특별시",
                "country": "대한민국",
                "country_code": "kr",
            }
            if korean
            else {
                "suburb": "Mok 5(o)-dong",
                "quarter": "Mok-dong",
                "borough": "Yangcheon-gu",
                "city": "Seoul",
                "country": "South Korea",
                "country_code": "kr",
            }
        )
        return self.FakeWeatherResponse({"address": address})

    def forecast_response(self, utc_offset_seconds=0, hourly_codes=None, daily_codes=None):
        hourly_codes = hourly_codes or [0, 1, 2, 3, 61, 61, 63, 65, 80, 0, 1, 2, 3, 61, 63, 65, 71, 73, 75, 95, 0, 1, 2, 3]
        daily_codes = daily_codes or [61, 0, 2, 3, 61, 71, 95]
        daily_dates = [
            "2026-06-25",
            "2026-06-26",
            "2026-06-27",
            "2026-06-28",
            "2026-06-29",
            "2026-06-30",
            "2026-07-01",
        ]
        return self.FakeWeatherResponse(
            {
                "utc_offset_seconds": utc_offset_seconds,
                "hourly": {
                    "time": [f"{day}T{hour:02d}:00" for day in daily_dates for hour in range(24)],
                    "weather_code": hourly_codes * len(daily_dates),
                    "temperature_2m": [
                        21.1 + hour * 0.4 + day_index
                        for day_index, _day in enumerate(daily_dates)
                        for hour in range(24)
                    ],
                    "relative_humidity_2m": [
                        70 + day_index
                        for day_index, _day in enumerate(daily_dates)
                        for _hour in range(24)
                    ],
                    "wind_speed_10m": [
                        2.0 + day_index * 0.1
                        for day_index, _day in enumerate(daily_dates)
                        for _hour in range(24)
                    ],
                },
                "daily": {
                    "time": daily_dates,
                    "weather_code": daily_codes,
                    "temperature_2m_min": [21.1, 22.2, 23.1, 24.0, 21.7, 20.2, 19.5],
                    "temperature_2m_max": [30.4, 31.2, 32.4, 29.7, 28.1, 26.4, 25.3],
                    "precipitation_probability_max": [60, 10, 20, 30, 55, 45, 75],
                },
            }
        )

    def met_forecast_response(self):
        start = datetime(2026, 6, 25, 0, 0)
        symbols = ["clearsky_day", "partlycloudy_day", "cloudy", "lightrain", "rain", "heavyrain", "rainshowers_day"]
        timeseries = []
        for index in range(36):
            current = start + timedelta(hours=index)
            symbol = symbols[index % len(symbols)]
            timeseries.append(
                {
                    "time": current.strftime("%Y-%m-%dT%H:%M:%SZ"),
                    "data": {
                        "instant": {
                            "details": {
                                "air_temperature": 21.0 + index * 0.2,
                                "relative_humidity": 60 + (index % 5),
                                "wind_speed": 2.0 + (index % 4) * 0.1,
                            }
                        },
                        "next_1_hours": {
                            "summary": {"symbol_code": symbol},
                            "details": {"precipitation_amount": 0.1 if "rain" in symbol else 0.0},
                        },
                    },
                }
            )
        return self.FakeWeatherResponse({"properties": {"timeseries": timeseries}})

